package counter

import "sync"

// Count runs n workers, each incrementing the shared total `per` times.
// Must return exactly n*per.
func Count(n, per int) int {
	total := 0
	var wg sync.WaitGroup
	for w := 0; w < n; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < per; i++ {
				total++
			}
		}()
	}
	wg.Wait()
	return total
}

test_setup_files.counter_race_test.go:
package counter

import "testing"

func TestCountExact(t *testing.T) {
	for round := 0; round < 3; round++ {
		got := Count(8, 20000)
		if got != 160000 {
			t.Fatalf("round %d: Count(8, 20000) = %d, want 160000 (lost updates)", round, got)
		}
	}
}

func TestCountSmall(t *testing.T) {
	if got := Count(1, 5); got != 5 {
		t.Fatalf("Count(1, 5) = %d, want 5", got)
	}
	if got := Count(4, 0); got != 0 {
		t.Fatalf("Count(4, 0) = %d, want 0", got)
	}
}

