package counter

import "sync"

// Count runs n workers, each incrementing the shared total `per` times.
func Count(n, per int) int {
	var mu sync.RWMutex
	total := 0
	var wg sync.WaitGroup
	for w := 0; w < n; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := 0; i < per; i++ {
				mu.RLock()
				total++
				mu.RUnlock()
			}
		}()
	}
	wg.Wait()
	return total
}
